<?php
namespace app\controller;use app\BaseController;use app\service\AdminAccess;use think\facade\Db;use think\facade\Session;use think\facade\View;
class Logs extends BaseController{public function index(){if($r=AdminAccess::guard())return $r;$q=trim((string)input('get.q',''));$status=trim((string)input('get.status',''));$endpoint=(int)input('get.endpoint_id',0);$user=(int)input('get.user_id',0);$key=(int)input('get.key_id',0);$from=trim((string)input('get.from',''));$to=trim((string)input('get.to',''));$page=max(1,(int)input('get.page',1));$size=30;$b=Db::name('request_logs')->alias('r')->leftJoin('endpoints e','e.id=r.endpoint_id')->leftJoin('users u','u.id=r.user_id')->leftJoin('keys k','k.id=r.key_id')->field('r.*,e.name endpoint_name,e.slug endpoint_slug,u.username,k.name key_name,k.key_prefix');if($q!=='')$b->whereLike('r.request_id|r.path|r.ip|u.username|k.name|k.key_prefix','%'.$q.'%');if($status==='success')$b->whereBetween('r.status_code',[200,399]);elseif($status==='error')$b->where('r.status_code','>=',400);if($endpoint)$b->where('r.endpoint_id',$endpoint);if($user)$b->where('r.user_id',$user);if($key)$b->where('r.key_id',$key);if($from!=='')$b->where('r.created_at','>=',$from.' 00:00:00');if($to!=='')$b->where('r.created_at','<=',$to.' 23:59:59');$count=(clone $b)->count();$items=$b->order('r.id','desc')->page($page,$size)->select()->toArray();View::assign(['items'=>$items,'username'=>Session::get('lumen_admin_username'),'endpoints'=>Db::name('endpoints')->field('id,name,slug')->order('name')->select()->toArray(),'users'=>Db::name('users')->field('id,username')->order('username')->select()->toArray(),'keys'=>Db::name('keys')->field('id,user_id,name,key_prefix')->order('id','desc')->limit(500)->select()->toArray(),'q'=>$q,'status'=>$status,'endpointId'=>$endpoint,'userId'=>$user,'keyId'=>$key,'from'=>$from,'to'=>$to,'page'=>$page,'pages'=>max(1,(int)ceil($count/$size)),'count'=>$count]);return View::fetch(root_path().'view/admin/logs.html');}}
